#!/usr/bin/env python3
"""Upgrade verified Agenda Clara 2.3 sources to local context rules 2.4.0."""
from pathlib import Path
import base64,zlib,json
src=Path("AgendaClara/app/src/main/java/pe/agendaclara/app")
sources=json.loads(zlib.decompress(base64.b64decode("")).decode("utf-8"))
for name,content in sources.items():
    if name not in ("ConversationAnalyzer.java","ConversationIntent.java"):raise RuntimeError("Unexpected source")
    (src/name).write_text(content,encoding="utf-8")
test=Path("AgendaClara/tests/ConversationTests.java")
s=test.read_text(encoding="utf-8")
old='check(found.size()==400,"Bounded 4000-message synthetic history analyzed");'
new='check(found.size()==1,"Repeated announcements from the same sender are grouped for review");'
if s.count(old)!=1:raise RuntimeError("Legacy duplicate regression anchor changed")
test.write_text(s.replace(old,new,1),encoding="utf-8")
phase8=Path("AgendaClara/tests/Phase8Tests.java")
phase8.write_bytes(zlib.decompress(base64.b64decode("")))
main=src/"MainActivity.java"
s=main.read_text(encoding="utf-8")
old='LinearLayout c=card(reviewList);c.setTag("proposal:"+p.id);c.setContentDescription("Propuesta pendiente: "+p.title);TextView badge=text(p.historical?"DEL HISTORIAL":"PARA REVISAR",10,GREEN,true);'
new='LinearLayout c=card(reviewList);c.setTag("proposal:"+p.id);c.setContentDescription("Propuesta pendiente: "+p.title);boolean isDateChange=p.reason!=null&&p.reason.contains("Cambio de fecha");TextView badge=text(isDateChange?"CAMBIO DE FECHA · CONFIRMAR":p.historical?"DEL HISTORIAL":"PARA REVISAR",10,isDateChange?RED:GREEN,true);'
if s.count(old)!=1:raise RuntimeError("Review chip anchor changed")
main.write_text(s.replace(old,new,1),encoding="utf-8")
gradle=Path("AgendaClara/app/build.gradle")
s=gradle.read_text(encoding="utf-8")
if s.count("versionCode 12")!=1 or s.count("versionName '2.3.0'")!=1:raise RuntimeError("Unexpected project version")
gradle.write_text(s.replace("versionCode 12","versionCode 13").replace("versionName '2.3.0'","versionName '2.4.0'"),encoding="utf-8")
print("Agenda Clara 2.4.0: contextual updates, explicit cancellations and repeated announcements.")
